using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncLifetime
{
    private HttpListener listener = null!;
    private HttpClient client = null!;
    private HttpStatusCode replyStatus = HttpStatusCode.OK;
    private string replyBody = "";
    private string? receivedMethod, receivedPath, receivedContentType, receivedBody;
    private Task serving = Task.CompletedTask;

    public Task InitializeAsync()
    {
        var port = GetFreePort();
        var prefix = $"http://127.0.0.1:{port}/";
        listener = new HttpListener();
        listener.Prefixes.Add(prefix);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
        serving = Task.Run(async () =>
        {
            while (listener.IsListening)
            {
                HttpListenerContext ctx;
                try { ctx = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                receivedMethod = ctx.Request.HttpMethod;
                receivedPath = ctx.Request.Url!.AbsolutePath;
                receivedContentType = ctx.Request.ContentType;
                using (var reader = new StreamReader(ctx.Request.InputStream, ctx.Request.ContentEncoding))
                    receivedBody = await reader.ReadToEndAsync();

                ctx.Response.StatusCode = (int)replyStatus;
                ctx.Response.ContentType = "application/json";
                var bytes = System.Text.Encoding.UTF8.GetBytes(replyBody);
                await ctx.Response.OutputStream.WriteAsync(bytes);
                ctx.Response.Close();
            }
        });
        return Task.CompletedTask;
    }

    public async Task DisposeAsync()
    {
        client.Dispose();
        listener.Close();
        await serving;
    }

    [Fact]
    public async Task The_authorization_is_posted_to_the_provider_with_the_agreed_json_shape()
    {
        Reply(HttpStatusCode.OK, """{"status":"approved"}""");

        await Gateway().AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        Assert.Equal("POST", receivedMethod);
        Assert.Equal("/v1/authorizations", receivedPath);
        Assert.StartsWith("application/json", receivedContentType);
        using var json = JsonDocument.Parse(receivedBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Reply(HttpStatusCode.OK, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Reply(HttpStatusCode.OK, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Reply(HttpStatusCode.OK, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_payment_the_provider_refuses_with_402_is_declined()
    {
        Reply(HttpStatusCode.PaymentRequired, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_with_an_empty_body_is_still_declined()
    {
        Reply(HttpStatusCode.PaymentRequired, "");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_failures_are_raised_rather_than_mistaken_for_a_decision(HttpStatusCode status)
    {
        Reply(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal(status, error.StatusCode);
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"result":"approved"}""")]
    [InlineData("null")]
    public async Task Anything_other_than_an_explicit_approval_is_never_treated_as_approved(string body)
    {
        Reply(HttpStatusCode.OK, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("not json")]
    [InlineData("")]
    [InlineData("""{"status":42}""")]
    public async Task An_unreadable_answer_is_raised_rather_than_approved(string body)
    {
        Reply(HttpStatusCode.OK, body);

        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    private HttpPaymentGateway Gateway() => new(client);

    private Task<AuthorizationOutcome> Authorize() =>
        Gateway().AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    private void Reply(HttpStatusCode status, string body)
    {
        replyStatus = status;
        replyBody = body;
    }

    private static int GetFreePort()
    {
        var tcp = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        var port = ((IPEndPoint)tcp.LocalEndpoint).Port;
        tcp.Stop();
        return port;
    }
}
EOF
